find-non-living-thing & 0 & 0 & 0 & 10 / 0 / 10 \\
\midrule
\textbf{Aggregate} & \textbf{41.4} & \textbf{11.4} & \textbf{+30.0} & \textbf{83 / 3 / 134} \\
